{
  "name": "@talgarr-boost/opencode-fusion",
  "version": "1.0.5",
  "description": "A tool-free lead and sidekick agent harness for OpenCode",
  "oc-plugin": [
    "server"
  ],
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "deno task build",
    "typecheck": "deno task typecheck",
    "test": "deno task test",
    "prepublishOnly": "deno task build"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/boost-rnd/opencode-fusion.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "devin-fusion",
    "multi-agent",
    "sidekick"
  ],
  "license": "MIT",
  "engines": {
    "node": ">=20.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "1.18.30"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.30",
    "esbuild": "0.25.12",
    "typescript": "5.9.3"
  }
}
